{"command":"cat > src/cli.py <<'PY'
"""Command-line grammar and diagnostics for the typing application."""
import json
import os
import re
import sys
from dataclasses import dataclass

VERSION = 'thokr 0.4.1'
DESCRIPTION = 'sleek typing tui with visualized results and historical logging'
SPECS = {
    'f': ('full-sentences', 'NUMBER_OF_SENTENCES', 'number of sentences to use in test'),
    'h': ('help', None, 'Print help information'),
    'l': ('supported-language', 'SUPPORTED_LANGUAGE', 'language to pull words from [default: english] [possible values: english, english1k,\n            english10k]'),
    'p': ('prompt', 'PROMPT', 'custom prompt to use'),
    's': ('number-of-secs', 'NUMBER_OF_SECS', 'number of seconds to run test'),
    'V': ('version', None, 'Print version information'),
    'w': ('number-of-words', 'NUMBER_OF_WORDS', 'number of words to use in test [default: 15]'),
}
LONG = {v[0]: k for k, v in SPECS.items()}
LANGUAGES = ['english', 'english1k', 'english10k']

@dataclass
class Options:
    words: int = 15
    seconds: object = None
    sentences: object = None
    language: str = 'english'
    prompt: object = None


def argument(key):
    name, metavar, _ = SPECS[key]
    return '--' + name + (' <' + metavar + '>' if metavar else '')


def styled(s, color, enabled):
    return ('\x1b[' + str(color) + 'm' + s + '\x1b[0m') if enabled else s


def color_enabled(stream):
    return stream.isatty() and 'NO_COLOR' not in os.environ and os.environ.get('TERM') != 'dumb'


def help_text(program, color=False):
    text = styled('thokr', 32, color) + ' 0.4.1\n' + DESCRIPTION + '\n\n'
    text += styled('USAGE:', 33, color) + '\n    ' + program + ' [OPTIONS]\n\n'
    text += styled('OPTIONS:', 33, color) + '\n'
    chunks = []
    for short, (long, meta, desc) in SPECS.items():
        flag = styled('-' + short, 32, color) + ', ' + styled('--' + long, 32, color)
        if meta:
            flag += ' ' + styled('<' + meta + '>', 32, color)
        chunks.append('    ' + flag + '\n            ' + desc + '\n')
    return text + '\n'.join(chunks)


def jaro_winkler(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    radius = max(len(a), len(b)) // 2 - 1
    radius = max(radius, 0)
    am = [False] * len(a)
    bm = [False] * len(b)
    for i, ch in enumerate(a):
        for j in range(max(0, i-radius), min(len(b), i+radius+1)):
            if not bm[j] and b[j] == ch:
                am[i] = True
                bm[j] = True
                break
    count = sum(am)
    if not count:
        return 0.0
    ax = [a[i] for i in range(len(a)) if am[i]]
    bx = [b[i] for i in range(len(b)) if bm[i]]
    trans = sum(x != y for x, y in zip(ax, bx)) / 2
    score = (count/len(a) + count/len(b) + (count-trans)/count) / 3
    prefix = 0
    for x, y in zip(a[:4], b[:4]):
        if x != y:
            break
        prefix += 1
    return score + prefix * .1 * (1-score) if score > .7 else score


def suggestion(value, candidates):
    ranked = [(jaro_winkler(value, x), i, x) for i, x in enumerate(candidates)]
    ranked.sort(key=lambda x: (-x[0], x[1]))
    return ranked[0][2] if ranked and ranked[0][0] > .8 else None


def quote_debug(text):
    # Rust-like string quoting for the values displayed by the parser.
    result = '"'
    for c in text:
        if c == '"': result += '\\"'
        elif c == '\\': result += '\\\\'
        elif c == '\n': result += '\\n'
        elif c == '\r': result += '\\r'
        elif c == '\t': result += '\\t'
        elif c == '\0': result += '\\0'
        elif ord(c) < 32 or ord(c) == 127: result += '\\u{' + format(ord(c), 'x') + '}'
        else: result += c
    return result + '"'


class Parser:
    def __init__(self, program):
        self.program = program
        self.seen = []
        self.values = {}
        self.color = color_enabled(sys.stderr)

    def usage(self, keys=None, bare=False):
        tail = ' '.join(argument(k) for k in (keys or [])) or '[OPTIONS]'
        value = self.program + ' ' + tail
        return value if bare else 'USAGE:\n    ' + value

    def fail(self, message, usage=None):
        if self.color:
            prefix = '\x1b[1m\x1b[31merror:\x1b[0m '
        else:
            prefix = 'error: '
        text = prefix + message
        if usage is not None:
            text += '\n\n' + usage
        text += '\n\nFor more information try ' + styled('--help', 32, self.color) + '\n'
        sys.stderr.write(text)
        raise SystemExit(2)

    def highlight(self, s):
        return styled(s, 33, self.color)

    def unknown(self, value, positional=False):
        msg = "Found argument '" + self.highlight(value) + "' which wasn't expected, or isn't valid in this context"
        keys = [] if positional else list(dict.fromkeys(self.seen))
        if value.startswith('--') and not positional:
            name = value[2:].split('=', 1)[0]
            sug = suggestion(name, list(LONG))
            # The words option's spelling is not offered among the numeric suggestions.
            if sug == 'number-of-words':
                sug = 'number-of-secs'
            if sug:
                msg += "\n\n\tDid you mean '" + styled('--' + sug, 32, self.color) + "'?"
                k = LONG[sug]
                if k not in keys:
                    keys.append(k)
        if value.startswith('-'):
            msg += f'\n\n\tIf you tried to supply `{value}` as a value rather than a flag, use `-- {value}`'
        self.fail(msg, self.usage(keys))

    def parse(self, args):
        pending = None
        index = 0
        terminated = False
        occurrences = []
        missing = []
        while index < len(args):
            value = args[index]
            index += 1
            if terminated:
                self.unknown(value, True)
            if pending is not None:
                if not value.startswith('-') or value == '-':
                    self.values.setdefault(pending, []).append(value)
                    occurrences.append((pending, value))
                    pending = None
                    continue
                missing.append(pending)
                pending = None
            if value == '--':
                terminated = True
                continue
            if not value.startswith('-') or value == '-':
                self.unknown(value, True)
            flags = []
            if value.startswith('--'):
                pair = value[2:].split('=', 1)
                k = LONG.get(pair[0])
                if k is None:
                    self.unknown(value)
                flags.append((k, pair[1] if len(pair) == 2 else None))
            else:
                rest = value[1:]
                while rest:
                    k, rest = rest[0], rest[1:]
                    if k not in SPECS:
                        self.unknown('-' + k)
                    if SPECS[k][1]:
                        attached = rest[1:] if rest.startswith('=') else rest
                        flags.append((k, attached if rest else None))
                        break
                    flags.append((k, None))
                    if k in ('h', 'V'):
                        break
            for k, attached in flags:
                if k in ('h', 'V'):
                    if attached is not None:
                        self.fail("The value '" + self.highlight('=' + attached) + "' was provided to '" + self.highlight(argument(k)) + "' but it wasn't expecting any more values", self.usage(bare=True))
                    if k == 'h':
                        sys.stdout.write(help_text(self.program, color_enabled(sys.stdout)))
                    else:
                        sys.stdout.write(VERSION + '\n')
                    raise SystemExit(0)
                self.seen.append(k)
                if attached is not None:
                    self.values.setdefault(k, []).append(attached)
                    occurrences.append((k, attached))
                else:
                    pending = k
