"""Typing state, per-second measurements, and append-only result history."""
import math
import os
import pwd
import time
from collections import Counter
from dataclasses import dataclass
from prompts import generate


def fixed(value, digits=0):
    if math.isnan(value):
        return 'NaN'
    if math.isinf(value):
        return 'inf' if value > 0 else '-inf'
    if digits == 0:
        return str(int(math.floor(value + .5))) if value >= 0 else str(int(math.ceil(value-.5)))
    return format(value, '.' + str(digits) + 'f')


@dataclass
class Stroke:
    character: str
    correct: bool
    elapsed: float


class Test:
    def __init__(self, options):
        self.options = options
        self.prompt = generate(options)
        self.reset()

    def reset(self):
        self.strokes = []
        self.started = None
        self.elapsed = 0.0
        self.done = not self.prompt or self.options.seconds == 0
        self.logged = False
        self.accuracy = 0.0
        self.wpm = 0.0
        self.deviation = 0.0
        self.points = []
        self.maximum = 0.0
        self.last_second = 1.0

    def new(self):
        self.prompt = generate(self.options, custom=False)
        self.reset()

    def update_time(self, now):
        if self.started is None or self.done:
            return False
        self.elapsed = max(0.0, math.floor((now - self.started) * 1000) / 1000)
        if self.options.seconds is not None and self.elapsed >= self.options.seconds:
            self.finish()
            return True
        return False

    def input(self, char, now, batch_elapsed=None):
        if self.done:
            if char == 'r':
                self.reset()
            elif char == 'n':
                self.new()
            return
        if self.started is None:
            self.started = now
            self.elapsed = 0.0
        else:
            self.elapsed = max(0.0, math.floor((now - self.started) * 1000) / 1000)
        i = len(self.strokes)
        if i >= len(self.prompt):
            return
        self.strokes.append(Stroke(char, char == self.prompt[i], self.elapsed))
        if len(self.strokes) >= len(self.prompt):
            self.finish()

    def backspace(self):
        if not self.done and self.strokes:
            self.strokes.pop()

    def calculate(self):
        total = len(self.strokes)
        good = [s for s in self.strokes if s.correct]
        self.accuracy = len(good) * 100.0 / total if total else float('nan')
        if not good:
            self.wpm = 0.0
            self.maximum = 0.0
            self.last_second = 1.0
            self.points = []
            self.deviation = 0.0
            return
        if self.elapsed == 0:
            self.points = [(0.0, float('inf'))]
            self.wpm = self.maximum = float('inf')
            self.last_second = 1.0
            self.deviation = 0.0
            return
        bins = Counter(max(1, math.ceil(stroke.elapsed)) for stroke in good)
        count = 0
        self.points = []
        for sec in sorted(bins):
            count += bins[sec]
            self.points.append((float(sec), count * 12.0 / sec))
        self.wpm = self.points[-1][1]
        self.maximum = max(point[1] for point in self.points)
        self.last_second = max(1.0, self.points[-1][0])
        whole = [bins[s] for s in sorted(bins)[:-1]]
        if whole:
            mean = sum(whole) / len(whole)
            self.deviation = math.sqrt(sum((n-mean)**2 for n in whole) / len(whole))
        else:
            self.deviation = 0.0

    def finish(self):
        if self.done:
            return
        self.done = True
        self.calculate()
        self.log()

    def log(self):
        if self.logged:
            return
        self.logged = True
        base = os.environ.get('XDG_CONFIG_HOME', '')
        if not os.path.isabs(base):
            home = os.environ.get('HOME') or pwd.getpwuid(os.getuid()).pw_dir
            base = os.path.join(home, '.config')
        directory = os.path.join(base, 'thokr')
        try:
            os.makedirs(directory, exist_ok=True)
            filename = os.path.join(directory, 'log.csv')
            new = not os.path.exists(filename)
            date = time.strftime('%a %b %e %H:%M:%S %Y', time.localtime())
            secs = '' if self.options.seconds is None else fixed(float(self.options.seconds), 2)
            row = [date, str(self.options.words), secs, fixed(self.elapsed, 2), fixed(self.wpm), fixed(self.accuracy), fixed(self.deviation, 2)]
            with open(filename, 'a', encoding='utf-8', newline='') as stream:
                if new:
                    stream.write('date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev\n')
                stream.write(','.join(row) + '\n')
        except (OSError, ValueError):
            pass
