import math
import os
import unicodedata
from model import fixed

BOLD, DIM, UNDERLINE, ITALIC = 1, 2, 4, 8
DEFAULT = (0, None)
FAINT = (BOLD | DIM, None)
CURSOR = (BOLD | DIM | UNDERLINE, None)
CORRECT = (BOLD, 2)
INCORRECT = (BOLD, 1)
EMPHASIS = (BOLD, None)
PURPLE = (0, 5)
ITALICS = (ITALIC, None)


def char_width(ch):
    if not ch or unicodedata.category(ch[0]) in ('Cc', 'Cf', 'Mn', 'Me'):
        return 0
    return 2 if unicodedata.east_asian_width(ch[0]) in ('W', 'F') else 1


def text_width(text):
    return sum(char_width(c) for c in text)


def clamp_size(w, h):
    w, h = max(0, min(65535, w)), max(0, min(65535, h))
    if w * h > 65535:
        scale = math.sqrt(65535.0 / (w * h))
        w, h = int(w * scale), int(h * scale)
    return w, h


class UnicodeBoundary(Exception):
    def __init__(self, prompt, index):
        self.prompt = prompt
        self.index = index
        p = 0
        self.character = ''
        self.start = 0
        self.end = 0
        for ch in prompt:
            n = len(ch.encode('utf-8'))
            if p < index < p+n:
                self.character, self.start, self.end = ch, p, p+n
                break
            p += n

    def message(self):
