class Grid:
    def __init__(self, width, height):
        self.width, self.height = width, height
        self.cells = [(' ', DEFAULT)] * (width * height)

    def put(self, x, y, ch, style=DEFAULT):
        if 0 <= x < self.width and 0 <= y < self.height:
            self.cells[y*self.width+x] = (ch, style)

    def text(self, x, y, text, style=DEFAULT, limit=None):
        right = self.width if limit is None else min(self.width, x + max(0, limit))
        for c in text:
            width = char_width(c)
            if x + width > right:
                break
            if width:
                self.put(x, y, c, style)
                for i in range(1, width):
                    self.put(x+i, y, '', style)
                x += width
        return x

    def styled_line(self, x, y, line, max_width):
        end = min(self.width, x + max_width)
        patch_flags, patch_color = DEFAULT
        for c, style in line:
            width = char_width(c)
            if x + width > end:
                break
            flags, color = style
            if not width:
                if c != '\n':
                    patch_flags |= flags
                    if color is not None:
                        patch_color = color
                continue
            flags |= patch_flags
            color = color if color is not None else patch_color
            self.put(x, y, c, (flags, color))
            for i in range(1, width):
                self.put(x+i, y, '', (flags, color))
            x += width
            patch_flags, patch_color = DEFAULT


def word_wrap(items, width):
    if width <= 0:
        return []
    # Newline characters in a span have no visible representation.
    items = [(c, s) for c, s in items if c != '\n']
    groups = []
    for item in items:
        whitespace = item[0].isspace()
        if groups and groups[-1][0] == whitespace:
            groups[-1][1].append(item)
        else:
            groups.append((whitespace, [item]))
    result = []
    line = []
    used = 0
    spaces = []
    for whitespace, group in groups:
        if whitespace:
            spaces += group
            continue
        word_width = sum(char_width(c) for c, _ in group)
        space_width = sum(char_width(c) for c, _ in spaces) if line else 0
        if line and used + space_width + word_width > width:
            result.append(line)
            line, used = [], 0
        if line:
            line += spaces
            used += space_width
        spaces = []
        for c, s in group:
            size = char_width(c)
            if used + size > width:
                if line:
                    result.append(line)
                line, used = [], 0
            if size <= width:
                line.append((c, s))
                used += size
