"""Raw terminal event handling. No external terminal library is required."""
import fcntl
import os
import re
import select
import signal
import struct
import termios
import time
import tty
from model import Test
from screen import Renderer, make_grid, clamp_size, UnicodeBoundary


class Keys:
    def __init__(self):
        self.buffer = b''
        self.escape_time = None

    def add(self, data, now):
        self.buffer += data
        if self.buffer.startswith(b'\x1b') and self.escape_time is None:
            self.escape_time = now

    def pop(self, now):
        b = self.buffer
        if not b:
            return None
        first = b[0]
        size = 1
        event = None
        if first == 27:
            if len(b) == 1:
                if self.escape_time is not None and now-self.escape_time < .025:
                    return None
                event = ('quit', None)
            elif b[1:2] in (b'[', b'O'):
                # Both normal and application-mode cursor sequences are accepted.
                match = re.match(br'\x1b(?:\[|O)[0-9;?<>]*([@-~])', b)
                if not match:
                    if len(b) < 64:
                        return None
                    event = ('ignore', None)
                    size = len(b)
                else:
                    size = match.end()
                    final = match.group(1)
                    if final == b'D': event = ('retry', None)
                    elif final == b'C': event = ('new', None)
                    else: event = ('ignore', None)
            elif b[1] == 27:
                event = ('quit', None)
            else:
                # Alt modifies a character but does not change its text.
                self.buffer = b[1:]
                self.escape_time = None
                return self.pop(now)
        elif first == 3:
            event = ('quit', None)
        elif first == 127:
            event = ('backspace', None)
        elif first in (9, 10, 13):
            event = ('ignore', None)
        elif first < 32:
            event = ('char', chr(first+96) if first else ' ')
        elif first < 128:
            event = ('char', chr(first))
        else:
            size = 2 if first < 224 else 3 if first < 240 else 4
            if len(b) < size:
                return None
            try:
                ch = b[:size].decode('utf-8')
            except UnicodeDecodeError:
                ch = '\ufffd'
                size = 1
            event = ('char', ch)
        self.buffer = b[size:]
        self.escape_time = now if self.buffer.startswith(b'\x1b') else None
        return event


def dimensions():
    for fd in (1, 0, 2):
        try:
            h, w, _, _ = struct.unpack('HHHH', fcntl.ioctl(fd, termios.TIOCGWINSZ, bytes(8)))
            return clamp_size(w, h)
        except OSError:
            pass
    return 80, 24


def write(data, fd=1):
    while data:
        n = os.write(fd, data)
        data = data[n:]


def run(options):
    test = Test(options)
    renderer = Renderer()
    keys = Keys()
    old_attrs = termios.tcgetattr(0)
    resize = [False]
    def resized(signum, frame):
        resize[0] = True
    old_handler = signal.signal(signal.SIGWINCH, resized)
    tty.setraw(0, termios.TCSANOW)
    write(b'\x1b[?1049h')
    panicked = False
    try:
        width, height = dimensions()
        write(renderer.draw(make_grid(test, width, height)))
        running = True
        while running:
            now = time.monotonic()
            if test.started is not None and not test.done:
                test.update_time(now)
            if resize[0]:
                resize[0] = False
                width, height = dimensions()
            write(renderer.draw(make_grid(test, width, height)))
            ready, _, _ = select.select([0], [], [], .01 if keys.buffer else .025)
            batch_time = time.monotonic()
            if ready:
                data = os.read(0, 65536)
                if not data:
                    break
                keys.add(data, batch_time)
            while True:
                event = keys.pop(time.monotonic())
                if event is None:
                    break
                kind, text = event
                if kind == 'quit':
                    running = False
                    break
                if kind == 'retry':
                    test.reset()
                elif kind == 'new':
                    test.new()
                elif kind == 'backspace':
                    test.backspace()
                elif kind == 'char':
                    test.input(text, batch_time)
                write(renderer.draw(make_grid(test, width, height)))
        return 0
    except UnicodeBoundary as error:
        panicked = True
        write(error.message().encode('utf-8'), 2)
        if renderer.hidden:
            write(b'\x1b[?25h')
        return 101
    finally:
        if not panicked:
            termios.tcsetattr(0, termios.TCSANOW, old_attrs)
            write(b'\x1b[?1049l\x1b[?25h')
        signal.signal(signal.SIGWINCH, old_handler)
