        if line:
            line += spaces
            used += space_width
        spaces = []
        for c, s in group:
            size = char_width(c)
            if used + size > width:
                if line:
                    result.append(line)
                line, used = [], 0
            if size <= width:
                line.append((c, s))
                used += size
    if line:
        result.append(line)
    return result or [[]]


def typing_grid(test, width, height):
    grid = Grid(width, height)
    inner_width = max(0, width - 10)
    n = len(test.strokes)
    raw_prompt = test.prompt.encode('utf-8')
    # The display advances a byte-sized cursor through the prompt.
    if n < len(raw_prompt):
        for index in (n, n+1):
            if index < len(raw_prompt) and raw_prompt[index] & 0xc0 == 0x80:
                raise UnicodeBoundary(test.prompt, index)
    if not inner_width:
        return grid
    estimate = max(1, math.ceil(len(raw_prompt) / inner_width))
    top = max(0, (height - 1) // 2 if estimate == 1 else (height - estimate - 1) // 2)
    if test.options.seconds is not None:
        remaining = max(0.0, test.options.seconds - test.elapsed)
        timer = fixed(remaining, 1)
        x = 5 + max(0, inner_width // 2 - text_width(timer) // 2)
        grid.text(x, top, timer, FAINT, inner_width)
        top += 2
    styled = []
    for i, c in enumerate(test.prompt):
        if i < n:
            good = test.strokes[i].correct
            style = CORRECT if good else INCORRECT
            if not good and c == ' ':
                c = '·'
        else:
            style = CURSOR if i == n else FAINT
        styled.append((c, style))
    lines = word_wrap(styled, inner_width)
    for i, line in enumerate(lines):
        if top+i >= height:
            break
        visible = sum(char_width(c) for c, _ in line)
        offset = max(0, inner_width // 2 - visible // 2) if estimate == 1 else 0
        grid.styled_line(5+offset, top+i, line, inner_width-offset)
    return grid


def bresenham(x0, y0, x1, y1):
    dx = abs(x1 - x0)
    dy = -abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    error = dx + dy
    while True:
        yield x0, y0
        if x0 == x1 and y0 == y1:
            break
        twice = 2 * error
        if twice >= dy:
            error += dy
            x0 += sx
        if twice <= dx:
            error += dx
            y0 += sy


def draw_chart(grid, test, x, y, width, height):
    if width <= 0 or height <= 0:
        return
    upper = fixed(test.maximum)
    label_width = min(len(upper), max(0, width // 3))
    axis_x = x + label_width
    graph_x = axis_x + 1
    graph_width = max(0, width - label_width - 1)
    graph_height = max(0, height - 2)
    right = x + width
    bottom = y + graph_height
    if graph_height > 0:
        # Draw the plot as an integer raster with eight braille dots per cell.
        if len(test.points) >= 2 and test.last_second > 1 and test.maximum > 0 and math.isfinite(test.maximum):
            rw, rh = graph_width * 2, graph_height * 4
            pixels = {}
            masks = ((1, 2, 4, 64), (8, 16, 32, 128))
            def point(v):
                xx, yy = v
                if not math.isfinite(xx) or not math.isfinite(yy) or xx < 1 or xx > test.last_second or yy < 0 or yy > test.maximum:
                    return None
                return (int((xx-1) * (rw-1) / (test.last_second-1)), int((test.maximum-yy) * (rh-1) / test.maximum))
            for a, b in zip(test.points, test.points[1:]):
                aa, bb = point(a), point(b)
                if aa is None or bb is None:
                    continue
                for px, py in bresenham(*aa, *bb):
                    if 0 <= px < rw and 0 <= py < rh:
                        cell = (px // 2, py // 4)
                        pixels[cell] = pixels.get(cell, 0) | masks[px % 2][py % 4]
            for (cx, cy), bits in pixels.items():
                grid.put(graph_x+cx, y+cy, chr(0x2800+bits), PURPLE)
        for yy in range(y, bottom):
            grid.put(axis_x, yy, '│')
        grid.text(x, y, upper, EMPHASIS, label_width)
        grid.text(x, bottom-1, '0', EMPHASIS, label_width)
        grid.put(axis_x, bottom, '└')
        for xx in range(axis_x+1, right):
            grid.put(xx, bottom, '─')
        grid.text(axis_x, bottom+1, '1', EMPHASIS, width-label_width)
        xmax = fixed(test.last_second, 2)
        if len(xmax) < graph_width:
            grid.text(right-len(xmax), bottom+1, xmax, EMPHASIS)
        if graph_height > 1:
            # Axis captions are on top of the plot; their rows use the axis style.
            for xx in range(graph_x, right):
                idx = y*grid.width + xx
                grid.cells[idx] = (grid.cells[idx][0], DEFAULT)
                idx = (bottom-1)*grid.width + xx
                grid.cells[idx] = (grid.cells[idx][0], DEFAULT)
            if graph_width >= 3:
                grid.text(graph_x, y, 'wpm')
            if graph_width >= 7:
                grid.text(right-7, bottom-1, 'seconds')
    else:
        # With no room for the plot, retain the part of the vertical axis that fits.
        grid.text(x, y, upper, EMPHASIS, label_width)
        grid.put(axis_x, y, '│')


def results_grid(test, width, height):
    grid = Grid(width, height)
    inner_width = max(0, width - 10)
    if inner_width <= 0 or height <= 4:
        return grid
    chart_height = max(0, height - 7)
    draw_chart(grid, test, 5, 2, inner_width, chart_height)
    summary = f'{fixed(test.wpm)} wpm   {fixed(test.accuracy)}% acc   {fixed(test.deviation, 2)} sd'
    x = 5 + max(0, inner_width//2 - len(summary)//2)
    sy = max(2, height-5)
    grid.text(x, sy, summary, EMPHASIS, inner_width-(x-5))
    grid.text(5, max(2, height-3), '(r)etry / (n)ew / (esc)ape', ITALICS, inner_width)
    return grid


def make_grid(test, w, h):
    return results_grid(test, w, h) if test.done else typing_grid(test, w, h)


def attributes(old, new):
    previous, old_color = old
    current, color = new
    remove = previous & ~current
    add = current & ~previous
    out = []
    if remove & (BOLD | DIM):
        out.append('\x1b[22m')
        if current & BOLD:
            out.append('\x1b[1m')
        if current & DIM:
            out.append('\x1b[2m')
    if remove & ITALIC:
        out.append('\x1b[23m')
    if remove & UNDERLINE:
        out.append('\x1b[24m')
    if add & BOLD:
        out.append('\x1b[1m')
    if add & ITALIC:
        out.append('\x1b[3m')
    if add & UNDERLINE:
        out.append('\x1b[4m')
    if add & DIM:
        out.append('\x1b[2m')
    if old_color != color:
        out.append('\x1b[39m' if color is None else f'\x1b[38;5;{color}m')
    return ''.join(out)


class Renderer:
    def __init__(self):
        self.previous = None
        self.hidden = False

    def draw(self, grid, force=False):
        out = []
        if self.previous is None or self.previous.width != grid.width or self.previous.height != grid.height:
            if self.previous is not None:
                out.append('\x1b[2J')
            self.previous = Grid(grid.width, grid.height)
        old = self.previous.cells
        last_x, last_y = -1, -1
        style = DEFAULT
        dirty = False
        skip = 0
        for i, cell in enumerate(grid.cells):
            if skip:
                skip -= 1
                continue
            glyph, new_style = cell
            if old[i] == cell and not force:
                continue
            if not glyph:
                continue
            y, x = divmod(i, grid.width)
            if (x, y) != (last_x, last_y):
                out.append(f'\x1b[{y+1};{x+1}H')
            out.append(attributes(style, new_style))
            style = new_style
            out.append(glyph)
            advance = max(1, char_width(glyph))
            last_x, last_y = x+advance, y
            skip = advance-1
            dirty = True
        if dirty or force:
            out.append('\x1b[39m\x1b[49m\x1b[0m\x1b[?25l')
            self.hidden = True
        elif not self.hidden:
            out.append('\x1b[?25l')
            self.hidden = True
        self.previous = grid
        return ''.join(out).encode('utf-8')
