def typing_positions(test, width, height):
    """Map visible ASCII prompt indices to cells for incremental key feedback."""
    if test.done or width <= 10 or any(ord(c) < 32 or ord(c) > 126 for c in test.prompt):
        return None
    iw = width - 10
    estimate = max(1, math.ceil(len(test.prompt) / iw))
    top = max(0, (height-1)//2 if estimate == 1 else (height-estimate-1)//2)
    if test.options.seconds is not None:
        top += 2
    items = []
    for i, c in enumerate(test.prompt):
        if i < len(test.strokes) and not test.strokes[i].correct and c == ' ':
            c = '·'
        items.append((c, i))
    positions = {}
    for dy, line in enumerate(word_wrap(items, iw)):
        if top+dy >= height:
            break
        used = len(line)
        x = 5 + (max(0, iw//2-used//2) if estimate == 1 else 0)
        for ch, index in line:
            positions[index] = (x, top+dy, ch)
            x += 1
    return positions


def patch_feedback(renderer, positions, updates):
    """Paint the few changed cells without scanning an otherwise unchanged frame."""
    changes = {}
    for index, style in updates:
        if index in positions:
            x, y, ch = positions[index]
            changes[y*renderer.previous.width+x] = (ch, style)
    out = []
    style = DEFAULT
    next_index = -1
    dirty = False
    for index in sorted(changes):
        cell = changes[index]
        if renderer.previous.cells[index] == cell:
            continue
        y, x = divmod(index, renderer.previous.width)
        if index != next_index or x == 0:
            out.append(f'\x1b[{y+1};{x+1}H')
        out.append(attributes(style, cell[1]))
        out.append(cell[0])
        style = cell[1]
        renderer.previous.cells[index] = cell
        next_index = index + 1
        dirty = True
    if dirty:
        out.append('\x1b[39m\x1b[49m\x1b[0m\x1b[?25l')
    return ''.join(out).encode('utf-8')
